import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        print([])
        return
    if '=' in data:
        n_str = data.split('=')[1].strip()
    else:
        n_str = data
    n = int(n_str)
    if n < 2:
        print([])
        return
    is_comp = [False] * (n + 1)
    primes = []
    for i in range(2, n + 1):
        if not is_comp[i]:
            primes.append(i)
        for p in primes:
            if p * i > n:
                break
            is_comp[p * i] = True
            if i % p == 0:
                break
    print(primes)

if __name__ == "__main__":
    main()
